{
  "findings": [
    {
      "check_id": "CKV_AZURE_224",
      "title": "Ledger is not enabled for the trading database",
      "resource": "azurerm_mssql_database.trading_database",
      "severity": "MEDIUM",
      "explanation": "This database is explicitly used for trading data, where tamper evidence and nonrepudiation are important. Without Azure SQL Ledger, unauthorized changes cannot be cryptographically verified."
    },
    {
      "check_id": "CKV_AZURE_229",
      "title": "Azure SQL Database is not zone redundant",
      "resource": "azurerm_mssql_database.trading_database",
      "severity": "MEDIUM",
      "explanation": "The database explicitly disables zone redundancy, leaving the trading workload vulnerable to an availability-zone failure. The current S2 tier does not support zone redundancy."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_database\" \"trading_database\" {\n  name           = \"trading-database\"\n  server_id      = azurerm_mssql_server.trading_sql_server.id\n  collation      = \"SQL_Latin1_General_CP1_CI_AS\"\n  license_type   = \"LicenseIncluded\"\n  max_size_gb    = 100\n  sku_name       = \"P1\"\n  ledger_enabled = true\n  zone_redundant = true\n}\n",
  "fix_summary": "Enabled Azure SQL Ledger to provide cryptographic integrity protection. Enabled zone redundancy and changed the database from S2 to the zone-redundancy-capable P1 tier."
}
